    { t: 'match', q: '【Cơ bản】Thân thể Bàn Cổ biến thành gì?', items: [['头发', '星星'], ['两眼', '太阳和月亮'], ['肌肉', '肥田沃土'], ['毛', '花草树木'], ['血脉', '河流']] },
    { t: 'tf', q: '【Cơ bản】Đúng hay sai?', items: [['神话是上古时代某一位作家创作的作品。', false], ['清白而轻的一半变成了地。', false], ['盘古怕天塌下来，就用头顶着天。', true], ['神话体现出中国人的世界观和人生观。', true]] },
    { t: 'fill', q: '【Trung bình】Điền từ.', items: [['很久很久以前，大地是一片___。', '混沌'], ['他用___打破了这个大鸡蛋。', '斧子'], ['浑浊而重的一半___下去变成地。', '沉'], ['___，盘古年老体衰，死去了。', '久而久之']] },
    { t: 'open', q: '【Sách · 思考题】Trả lời câu hỏi.', items: [['熟读《盘古开天辟地》，然后分析其思想内容及意义。', '故事解释了天地的形成和万物的来源：混沌如鸡蛋，轻清者上升为天，重浊者下沉为地；盘古死后身体化为日月星辰、山川草木。它体现了古人朴素的宇宙观（阴阳、天人合一），歌颂了盘古开创世界、献身的精神，表现出民间作者丰富大胆的想象力。'], ['收集有关中国人征服大自然的神话传说，选择一个向全班同学介绍。', '例：《后羿射日》《精卫填海》《大禹治水》《夸父逐日》。可介绍故事内容＋表现的精神（不怕困难、与自然斗争）。']] }
