    { t: 'match', q: '【Cơ bản】Nối trường phái với nhà thơ tiêu biểu.', items: [['浪漫主义', '李白'], ['现实主义', '杜甫'], ['田园山水', '王维、孟浩然'], ['边塞', '王昌龄、岑参、高适']] },
    { t: 'match', q: '【Cơ bản】Nối biệt hiệu với nhà thơ.', items: [['诗仙', '李白'], ['诗圣', '杜甫'], ['小李杜', '李商隐和杜牧'], ['神童', '王勃']] },
    { t: 'mc', q: '【Trung bình】Chọn đáp án đúng.', items: [['安史之乱后唐朝人口下降到：', ['八千多万', '一千七百多万', '一亿多'], 1], ['唐律诗中需要对仗的是：', ['首联和尾联', '颔联和颈联', '首联和颔联'], 1], ['唐朝诗歌发展的过渡阶段是：', ['汉朝', '隋朝', '宋朝'], 1], ['“诗史”指的是谁的诗？', ['李白', '杜甫', '王维'], 1], ['八句的律诗分为几联？', ['两联', '三联', '四联'], 2]] },
    { t: 'tf', q: '【Trung bình】Đúng hay sai?', items: [['唐太宗和唐玄宗都爱好诗歌。', true], ['李白是现实主义诗人。', false], ['边塞诗又叫出塞诗。', true], ['越南人把律诗的颔联叫做“luận”。', false], ['晚唐时期的著名诗人有杜牧和李商隐。', true]] },
    { t: 'open', q: '【Sách · 思考题】', items: [
      ['唐诗为何很快登上了高峰？', '1. 唐朝空前强大统一，经济繁荣，交通发达，儒释道并存；2. 安史之乱带来的生离死别成为无穷的题材；3. 君王爱慕诗歌，处处兴起献诗运动；4. 隋朝的诗歌改革奠定了基础。'],
      ['唐诗的四个发展阶段及其代表诗人？', '初唐：初唐四杰（王勃、杨炯、卢照邻、骆宾王）、陈子昂；盛唐：李白、杜甫、王维、孟浩然、王昌龄、王之涣；中唐：白居易、刘禹锡、孟郊、贾岛；晚唐：杜牧、李商隐（小李杜）。'],
      ['唐朝诗歌可分为哪几个创作流派？每个流派的代表诗人是谁？', '四个流派：浪漫主义（李白）、现实主义（杜甫）、田园山水（王维、孟浩然）、边塞（王昌龄、岑参、高适、王之涣）。']] }
