    { t: 'match', q: '【Cơ bản】Nối các vế đối trong thơ.', items: [['感时', '恨别'], ['花', '鸟'], ['溅泪', '惊心'], ['烽火', '家书'], ['连三月', '抵万金']] },
    { t: 'mc', q: '【Trung bình】Chọn đáp án đúng.', items: [['《春望》写于什么时期？', ['开元盛世', '安史之乱期间', '晚唐'], 1], ['《春望》写于哪个城市？', ['长安', '洛阳', '成都'], 0], ['“安史之乱”的“史”指的是：', ['史书', '史思明', '历史'], 1], ['“白头搔更短”中“更短”说明了什么？', ['头发剪了', '愁的程度很深', '天气很冷'], 1], ['全诗的风格是：', ['豪放飘逸', '沉郁悲壮', '清新自然'], 1]] },
    { t: 'tf', q: '【Trung bình】Đúng hay sai?', items: [['杜甫是浪漫主义诗人。', false], ['“家书抵万金”说明战乱中家信非常珍贵。', true], ['《春望》的前四句写诗人思念亲人。', false], ['对“感时花溅泪”有两种解释。', true], ['杜甫在投奔肃宗途中被叛军俘获。', true]] },
    { t: 'open', q: '【Nâng cao】Trả lời câu hỏi.', items: [['“感时花溅泪，恨别鸟惊心”有哪两种解释？', '一种：花鸟本是娱人之物，诗人因感时恨别，见了花鸟反而落泪惊心（触景生情）；另一种：以花鸟拟人，花也溅泪，鸟也惊心（移情于物）。两说都表达了感时伤世之情。'], ['“白头搔更短，浑欲不胜簪”对刻画诗人形象起了什么作用？', '白发是因愁所致，“搔”是想解愁的动作，“更短”可见愁之深，刻画出一个因忧国思家而迅速衰老的诗人形象，增添了一层悲哀。']] }
