    { t: 'fill', q: '【Trung bình】Điền vào chỗ trống.', items: [['《三里湾》围绕秋收、整党、扩社、___四件事展开。', '开渠'], ['《山乡巨变》中的女主人公是___。', '邓秀梅'], ['《山乡巨变》的故事发生在湖南的___乡。', '清溪'], ['《创业史》的作者是___。', '柳青']] },
    { t: 'open', q: '【Sách · 思考题】', items: [['为什么“农村题材”小说成为“十七年”文学重要的创作题材？', '五四以来农村题材一直受关注；建国后农村发生巨大变化，合作化和人民公社化运动使农村问题成为全社会关注的问题；作家深入农村，熟悉农民生活，因此农村题材小说在数量和质量上都取得惊人成就，成为当代文学的“一枝独秀”。'], ['按照流派来分，“十七年”时期的农村小说可分为几个派别？其代表作家是谁？', '三个派别：“山药蛋派”（赵树理、马烽、西戎、束为、孙谦）、“荷花淀派”（孙犁、刘绍棠、从维熙、房树民）、“茶子花派”（周立波等）。']] }
