    { t: 'mc', q: '【Cơ bản】Chọn đáp án đúng.', items: [['“伤痕文学”的发端之作是：', ['《伤痕》', '《班主任》', '《将军吟》'], 1], ['《班主任》的作者是：', ['卢新华', '刘心武', '王蒙'], 1], ['《伤痕》发表在：', ['《人民文学》', '《文汇报》', '《新青年》'], 1], ['谢惠敏一看到《牛虻》的插图就认定它是：', ['好书', '“黄书”', '外国书'], 1], ['《班主任》发出的时代呼声是：', ['救救孩子', '解放思想', '改革开放'], 0]] },
    { t: 'match', q: '【Cơ bản】Nối nhân vật với tác phẩm.', items: [['宋宝琦', '《班主任》'], ['谢惠敏', '《班主任》'], ['张俊石', '《班主任》'], ['王晓华', '《伤痕》'], ['许茂', '《许茂和他的女儿们》']] },
    { t: 'fill', q: '【Trung bình】Điền vào chỗ trống.', items: [['伤痕文学使文学从政治的___地位中挣脱出来。', '附庸'], ['伤痕文学在展示伤痕的同时，沉痛地呼唤___的回归。', '人性'], ['王晓华的母亲被“四人帮”定为“___”。', '叛徒']] },
    { t: 'open', q: '【Sách · 问答题】', items: [['“伤痕文学”有什么特点？', '1. 以《班主任》为发端，大量表现“文革”给人们带来的身心伤害，真实反映社会心理；2. 突破思想禁区，展示伤痕，呼唤人性回归；3. 使文学从政治附庸中挣脱出来，回到真实；4. 感情强烈、充满悲愤，但艺术上尚嫌生硬和戏剧化；5. 改变了以往单一的颂歌格调。'], ['为什么说谢惠敏这个形象比宋宝琦更有典型意义？', '宋宝琦是明显的“坏孩子”，而谢惠敏表面上是品学兼优的好学生，却同样愚昧僵化，说明“四人帮”的毒害不只在表面，而是深入“好孩子”的灵魂，因此更深刻、更普遍、更典型。']] }
